   * @resultadoEsperado Após remover, obter devolve null
   */
  test('remove o token', () => {
    tokenStorage.salvar('jwt-123');
    tokenStorage.remover();
    expect(tokenStorage.obter()).toBeNull();
  });

  /**
   * @caso CT-UNI-362
   * @nivel unitario
   * @atributo compatibilidade
   * @subatributo interoperabilidade
