  });

  /**
   * @caso CT-UNI-363
   * @nivel unitario
   * @atributo confiabilidade
   * @subatributo tolerancia-a-falhas
   * @requisito RNF04
   * @objetivo Iniciar sem sessão quando não há token gravado
