    await waitFor(() => expect(linhas()).toHaveLength(2));
    fireEvent.change(within(linhas()[0]).getByLabelText('Fim'), { target: { value: '11:00' } });
    expect(medicosApi.salvarGrade).not.toHaveBeenCalled();
